/* Standalone page reset */
html, body { margin: 0; padding: 0; min-height: 100%; }
body { min-height: 100vh; }

/* Scoped reset — Figma has no default margins */
.dashboard, .dashboard *, .dashboard *::before, .dashboard *::after { box-sizing: border-box; }
.dashboard :where(h1, h2, h3, p, ul, li, figure) { margin: 0; padding: 0; }
.dashboard :where(button) { border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; }
.dashboard :where(a) { color: inherit; text-decoration: none; }
.dashboard :where(img) { display: block; }

.dashboard {
  display: flex;
  flex-direction: column;
  padding: 24px;
  gap: 16px;
  width: 420px;
  background: #FFFFFF;
  font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.dashboard__title {
  color: #111827;
  font-size: 18px;
  font-weight: 600;
  line-height: 20px;
  white-space: nowrap;
}

.dashboard__stats {
  display: flex;
  flex-direction: row;
  gap: 12px;
  align-self: stretch;
  padding: 0;
  margin: 0;
  list-style: none;
}

.stat-card {
  display: flex;
  flex-direction: column;
  padding: 16px;
  gap: 4px;
  border-radius: 12px;
  background: #F9FAFB;
  flex: 1 0 0;
}

.stat-card__label {
  color: #6B7280;
  font-size: 12px;
  font-weight: 400;
  line-height: 20px;
  white-space: nowrap;
}

.stat-card__value {
  color: #111827;
  font-size: 20px;
  font-weight: 700;
  line-height: 20px;
  white-space: nowrap;
}

.primary-button {
  display: flex;
  flex-direction: row;
  padding: 12px 24px;
  border-radius: 8px;
  background: #0D99FF;
  justify-content: center;
}

.primary-button__text {
  color: #FFFFFF;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  white-space: nowrap;
}
